  AND BASE_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}
  AND TARGET_CURRENCY = #{targetCurrency,jdbcType=VARCHAR}
  AND RATE_TYPE = #{rateType,jdbcType=VARCHAR}
  AND ROWNUM = 1
ORDER BY CREATE_TIME DESC

SELECT 
FROM TC_EXCHANGE_RATE


        AND BASE_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}


        AND TARGET_CURRENCY = #{targetCurrency,jdbcType=VARCHAR}


        AND RATE_TYPE = #{rateType,jdbcType=VARCHAR}


        AND DATA_SOURCE = #{dataSource,jdbcType=VARCHAR}


        AND RATE_DATE >= #{startDate,jdbcType=DATE}


        AND RATE_DATE <= #{endDate,jdbcType=DATE}


        AND STATUS = #{status,jdbcType=VARCHAR}


ORDER BY RATE_DATE DESC, CREATE_TIME DESC

SELECT 
FROM TC_EXCHANGE_RATE
WHERE BASE_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}
  AND TARGET_CURRENCY = #{targetCurrency,jdbcType=VARCHAR}
  AND RATE_TYPE = #{rateType,jdbcType=VARCHAR}
  AND STATUS = '1'
ORDER BY RATE_DATE DESC, CREATE_TIME DESC
AND ROWNUM = 1

SELECT 
FROM TC_EXCHANGE_RATE
WHERE BASE_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}
  AND TARGET_CURRENCY = #{targetCurrency,jdbcType=VARCHAR}
  AND RATE_TYPE = #{rateType,jdbcType=VARCHAR}
  AND RATE_DATE BETWEEN #{startDate,jdbcType=DATE} AND #{endDate,jdbcType=DATE}
ORDER BY RATE_DATE ASC

SELECT CASE
    WHEN EXISTS (
        SELECT 1 FROM TC_EXCHANGE_RATE
        WHERE BASE_CURRENCY = #{fromCurrency,jdbcType=VARCHAR}
          AND TARGET_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}
          AND RATE_DATE = #{rateDate,jdbcType=DATE}
          AND RATE_TYPE = #{rateType,jdbcType=VARCHAR}
    ) AND EXISTS (
        SELECT 1 FROM TC_EXCHANGE_RATE
        WHERE BASE_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}
          AND TARGET_CURRENCY = #{toCurrency,jdbcType=VARCHAR}
          AND RATE_DATE = #{rateDate,jdbcType=DATE}
          AND RATE_TYPE = #{rateType,jdbcType=VARCHAR}
    ) THEN (
        SELECT (r1.EXCHANGE_RATE * r2.EXCHANGE_RATE)
        FROM TC_EXCHANGE_RATE r1, TC_EXCHANGE_RATE r2
        WHERE r1.BASE_CURRENCY = #{fromCurrency,jdbcType=VARCHAR}
          AND r1.TARGET_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}
          AND r1.RATE_DATE = #{rateDate,jdbcType=DATE}
          AND r1.RATE_TYPE = #{rateType,jdbcType=VARCHAR}
          AND r2.BASE_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}
          AND r2.TARGET_CURRENCY = #{toCurrency,jdbcType=VARCHAR}
          AND r2.RATE_DATE = #{rateDate,jdbcType=DATE}
          AND r2.RATE_TYPE = #{rateType,jdbcType=VARCHAR}
    )
    ELSE NULL
END AS crossRate
FROM DUAL

SELECT COUNT(1)
FROM TC_EXCHANGE_RATE
WHERE RATE_DATE = #{rateDate,jdbcType=DATE}
  AND BASE_CURRENCY = #{baseCurrency,jdbcType=VARCHAR}
  AND TARGET_CURRENCY = #{targetCurrency,jdbcType=VARCHAR}
  AND RATE_TYPE = #{rateType,jdbcType=VARCHAR}

